mapper.insert:
INSERT INTO COMM_DEPARTMENT (
DEPID , DEPCODE , LOCATION , DEPGRADE , COMPID , ADMINID , EFFECTDATE , ISDISABLED , DISABLEDDATE , REMARK , UPDATEFLG , LASTUPDATEDATE , DEPIDHR , DIRECTOR , DEPCHARGE , DISPLAYCODE ,
) VALUES(
#{depid} , #{depcode} , #{location} , #{depgrade} , #{compid} , #{adminid} , #{effectdate} , #{isdisabled} , #{disableddate} , #{remark} , #{updateflg} , #{lastupdatedate} , #{depidhr} , #{director} , #{depcharge} , #{displaycode} ,
)

mapper.select:
SELECT
FROM COMM_DEPARTMENT WHERE DEPID=#{depIdVal}
DEPID=#{depid} AND LOCATION=#{location} AND

select a.ID, a.PCODE, case a.ID when ${pidVal} then substr(a.text, 0, instr(a.text, '_', 1) - 1) else a.text end text, a.PID, a.ATTR, a.TEXTPY, a.displaycode, a.ORD from (select a.*, ord from (select 'dep' || t.depid id, t.depcode pcode, substr(t.location, instr(t.location, '-', 1) + 1, Length(t.location)) text, 'org' || t.compid pid, 'dep' attr, to_char(t.depid) textpy, t.displaycode from comm_department t where t.isdisabled = '0' and t.depcode = #{code}
union all select 'dep' || t.depid id, t.depcode pcode, substr(t.location, instr(t.location, '-', 1) + 1, Length(t.location)) text, decode(m.centerid, null, 'dep' || t.adminid, 'cen' || m.centerid) pid, 'dep' attr, to_char(t.depid) textpy, t.displaycode from comm_department t left join ppm_da_dept_manager m on t.depid = m.deptid where t.adminid is not null and t.isdisabled = '0' and t.adminid = #{depIdVal}
union all select 'gro' || ga.id id, ga.id pcode, ga.groupname text, 'dep' || ga.depid pid, 'gro' attr, to_char(ga.depid) textpy, '' displaycode from ppm_da_team_group ga where ga.isdel = '0'
union all select 'cen' || m.id id, to_char(m.id) pcode, m.centername text, ${pidVal} pid, 'cen' attr, to_char(m.id) textpy, '' displaycode from Ppm_Da_Center m) a left join ppm_dept_ord o on a.id = o.depid start with a.pcode in (select #{code} from dual) connect by prior a.id = a.pid ) a order by PCODE

SELECT A.DEPGRADE FROM COMM_DEPARTMENT A WHERE A.DEPID = (
SELECT T.DEPID FROM PPM_EMP_VIEW T WHERE T.BADGE = #{userId}
)
